(function($){var prefix='automatorwp-dailybot-';var _prefix = 'automatorwp_dailybot_';$('body').on('click','#'+_prefix+'authorize',function(e){e.preventDefault();var button=$(this);var wrapper=button.parent();var key=$('#'+_prefix+'key').val();var response_wrap = wrapper.find('#'+_prefix+'response');if(!response_wrap.length){wrapper.append('<div id="'+_prefix + 'response" style="display: none; margin-top: 10px;"></div>');response_wrap=wrapper.find('#'+ _prefix+'response');}if(key.length===0){response_wrap.addClass('automatorwp-notice-error');response_wrap.html('All fields are required to connect with Dailybot.');response_wrap.slideDown('fast');return;}response_wrap.slideUp('fast');response_wrap.attr('class','');wrapper.append('<span class="spinner is-active" style="float:none;"></span>');button.prop('disabled',true);$.post(ajaxurl,{action:'automatorwp_dailybot_authorize',nonce:automatorwp_dailybot.nonce,key:key},function(response){response_wrap.addClass('automatorwp-notice-'+(response.success===true?'success':'error'));response_wrap.html((response.data.message!==undefined?response.data.message:response.data));response_wrap.slideDown('fast');wrapper.find('.spinner').remove();if(response.success===true&&response.data.redirect_url!==undefined){window.location=response.data.redirect_url;return;}button.prop('disabled',false);})});})(jQuery);